<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><div class="toolbar"><form><select name="status" onchange="this.form.submit()"><option value="">All statuses</option><?php foreach(['pending','processing','shipped','delivered','cancelled'] as $s): ?><option <?= service('request')->getGet('status')===$s?'selected':'' ?>><?= $s ?></option><?php endforeach ?></select></form></div><div class="table-wrap"><table><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Payment</th><th>Date</th></tr><?php foreach($rows as $r): ?><tr><td><a href="<?= base_url('admin/orders/'.$r['id']) ?>"><?= esc(order_number($r)) ?></a></td><td><?= esc($r['email']) ?></td><td>₹<?= number_format($r['total_amount'],2) ?></td><td><?= $r['status'] ?></td><td><?= $r['payment_status'] ?></td><td><?= date('d M Y',strtotime($r['created_at'])) ?></td></tr><?php endforeach ?></table></div><?= $this->endSection() ?>
